export default function makeController() {
  const dt = 0.01;
  const g = 9.81;
  const nominalMass = 0.725;
  const maxTotalThrust = 16.0;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  let initialized = false;
  let vf = { x: 0, y: 0, z: 0 };
  let prevVf = { x: 0, y: 0, z: 0 };
  let prevCmdAcc = { x: 0, y: 0, z: 0 };
  let dSlow = { x: 0, y: 0, z: 0 };
  let dFast = { x: 0, y: 0, z: 0 };

  let refPos = { x: 0, y: 0, z: 0 };
  let refVel = { x: 0, y: 0, z: 0 };

  let intPos = { x: 0, y: 0, z: 0 };
  let intYaw = 0;

  let targetIndex = -1;
  let phase = 'align';
  let settle = 0;
  let lockedGate = null;
  let padY = 0.95;

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att;

      if (!initialized) {
        initialized = true;
        vf = { x: v.x, y: v.y, z: v.z };
        prevVf = { x: v.x, y: v.y, z: v.z };
        refPos = { x: p.x, y: Math.max(p.y, 0.3), z: p.z };
      }

      // 1. Filter velocity
      const alphaV = 0.45;
      vf.x += alphaV * (v.x - vf.x);
      vf.y += alphaV * (v.y - vf.y);
      vf.z += alphaV * (v.z - vf.z);

      // 2. Fast/slow accel disturbance observer
      const measAcc = {
        x: (vf.x - prevVf.x) / dt,
        y: (vf.y - prevVf.y) / dt,
        z: (vf.z - prevVf.z) / dt,
      };
      prevVf = { x: vf.x, y: vf.y, z: vf.z };

      if (obs.t > 0.08 && p.y > 0.11) {
        const rawDist = {
          x: clamp(measAcc.x - prevCmdAcc.x, -12, 12),
          y: clamp(measAcc.y - prevCmdAcc.y, -8, 8),
          z: clamp(measAcc.z - prevCmdAcc.z, -12, 12),
        };
        const alphaSlow = 0.03;
        const alphaFast = 0.22;
        for (const k of ['x', 'y', 'z']) {
          dSlow[k] = clamp(dSlow[k] + alphaSlow * (rawDist[k] - dSlow[k]), -6, 6);
          dFast[k] = clamp(dFast[k] + alphaFast * (rawDist[k] - dFast[k]), -9, 9);
        }
      } else {
        dFast.x *= 0.9; dFast.y *= 0.9; dFast.z *= 0.9;
      }

      // 3. Navigation: gate exit lock, predictive cross abort, ramp pad descent
      let rawTarget = { x: p.x, y: 0.95, z: p.z };

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          if (targetIndex >= 0 && lockedGate && p.x < lockedGate.x + 0.18) {
            rawTarget = { x: lockedGate.x + 0.30, y: lockedGate.y, z: lockedGate.z };
          } else {
            targetIndex = obs.gateIndex;
            lockedGate = { x: gate.x, y: gate.y, z: gate.z };
            phase = 'align';
            settle = 0;
            intPos = { x: 0, y: 0, z: 0 };
          }
        }

        if (targetIndex === obs.gateIndex) {
          if (p.x > gate.x + 0.05 && phase !== 'cross') {
            phase = 'recover';
          }
          if (phase === 'recover') {
            const dz = p.z - gate.z, dy = p.y - gate.y;
            if (p.x > gate.x - 0.25 && Math.abs(dz) < 0.55 && Math.abs(dy) < 0.55) {
              const safeY = clamp(gate.y + (dy >= 0 ? 0.62 : -0.62), 0.35, 2.65);
              rawTarget = { x: p.x, y: safeY, z: gate.z };
              if (Math.abs(p.y - gate.y) > 0.48 || Math.abs(p.z - gate.z) > 0.58) {
                rawTarget = { x: gate.x - 0.50, y: safeY, z: gate.z };
              }
            } else {
              phase = 'align';
              settle = 0;
            }
          }

          if (phase === 'align') {
            rawTarget = { x: gate.x - 0.42, y: gate.y, z: gate.z };
            const ey = Math.abs(gate.y - p.y);
            const ez = Math.abs(gate.z - p.z);
            const ex = Math.abs(rawTarget.x - p.x);
            const vy = Math.abs(vf.y), vz = Math.abs(vf.z);
            if (ex < 0.18 && ey < 0.075 && ez < 0.065 && vy < 0.28 && vz < 0.25 && Math.abs(vf.x) < 0.45) {
              settle++;
            } else {
              settle = Math.max(0, settle - 1);
            }
            if (settle >= 8) {
              phase = 'cross';
              intPos.y *= 0.5;
              intPos.z *= 0.5;
            }
          }

          if (phase === 'cross') {
            const dx = gate.x - p.x;
            if (dx > 0.03) {
              const vxEff = Math.max(vf.x, 0.35);
              const tCross = clamp(dx / vxEff, 0.02, 0.45);
              const predY = p.y + vf.y * tCross + 0.5 * dFast.y * tCross * tCross;
              const predZ = p.z + vf.z * tCross + 0.5 * dFast.z * tCross * tCross;
              const curEy = Math.abs(p.y - gate.y);
              const curEz = Math.abs(p.z - gate.z);
              const predEy = Math.abs(predY - gate.y);
              const predEz = Math.abs(predZ - gate.z);

              const canStop = dx > 0.12 || vf.x < 0.65;
              if (canStop && (predEy > 0.165 || predEz > 0.095 || curEy > 0.175 || curEz > 0.10)) {
                phase = 'align';
                settle = 0;
                rawTarget = { x: gate.x - 0.42, y: gate.y, z: gate.z };
              } else {
                rawTarget = { x: gate.x + 0.35, y: gate.y, z: gate.z };
              }
            } else {
              rawTarget = { x: gate.x + 0.35, y: gate.y, z: gate.z };
            }
          }
        }
      } else {
        const pad = obs.pad.centre;
        if (targetIndex !== 3) {
          if (lockedGate && p.x < lockedGate.x + 0.18) {
            rawTarget = { x: lockedGate.x + 0.30, y: lockedGate.y, z: lockedGate.z };
          } else {
            targetIndex = 3;
            phase = 'pad_approach';
            padY = Math.max(0.65, Math.min(1.05, p.y));
            intPos = { x: 0, y: 0, z: 0 };
          }
        }
        if (targetIndex === 3) {
          const distH = Math.hypot(pad.x - p.x, pad.z - p.z);
          const speedH = Math.hypot(vf.x, vf.z);
          if (phase === 'pad_approach') {
            rawTarget = { x: pad.x, y: padY, z: pad.z };
            if (distH < 0.35) {
              padY = Math.max(0.32, padY - 0.45 * dt);
              rawTarget.y = padY;
            }
            if (distH < 0.11 && speedH < 0.25) {
              phase = 'descend';
            }
          }
          if (phase === 'descend') {
            if (distH < 0.13) {
              const rate = p.y > 0.22 ? 0.55 : 0.25;
              padY = Math.max(0.04, padY - rate * dt);
            } else if (distH > 0.16 && p.y > 0.12) {
              padY = Math.min(0.30, Math.max(padY, p.y));
            }
            rawTarget = { x: pad.x, y: padY, z: pad.z };
          }
        }
      }

      // 4. Smooth ref filter
      const wn = phase === 'cross' ? 7.5 : 5.5;
      const zeta = 0.95;
      const maxVel = phase === 'cross' ? 1.5 : 1.7;
      const maxAcc = 4.5;
      for (const k of ['x', 'y', 'z']) {
        const err = rawTarget[k] - refPos[k];
        let desVel = clamp(wn * err, -maxVel, maxVel);
        let acc = clamp(2 * zeta * wn * (desVel - refVel[k]), -maxAcc, maxAcc);
        refVel[k] = clamp(refVel[k] + acc * dt, -maxVel, maxVel);
        refPos[k] += refVel[k] * dt;
      }

      // 5. Local position integrals
      const locErr = {
        x: rawTarget.x - p.x,
        y: rawTarget.y - p.y,
        z: rawTarget.z - p.z,
      };
      for (const k of ['x', 'y', 'z']) {
        if (Math.abs(locErr[k]) < 0.35) {
          intPos[k] = clamp(intPos[k] + locErr[k] * dt, -0.45, 0.45);
        } else {
          intPos[k] *= 0.98;
        }
      }

      // 6. Position PD + Feedforward + Disturbance Rejection + Local Integrals
      const kp = phase === 'cross' ? { x: 4.8, y: 7.5, z: 7.5 } : { x: 4.5, y: 6.5, z: 4.8 };
      const kd = phase === 'cross' ? { x: 3.6, y: 4.5, z: 4.8 } : { x: 3.6, y: 4.2, z: 3.8 };
      const ki = { x: 1.2, y: 2.2, z: 1.4 };

      const distComp = {
        x: 0.75 * dFast.x + 0.25 * dSlow.x,
        y: 0.40 * dFast.y + 0.60 * dSlow.y,
        z: 0.75 * dFast.z + 0.25 * dSlow.z,
      };

      const ex = ( 0.65 * (refPos.x - p.x) + 0.35 * (rawTarget.x - p.x) );
      const ey = ( 0.65 * (refPos.y - p.y) + 0.35 * (rawTarget.y - p.y) );
      const ez = ( 0.65 * (refPos.z - p.z) + 0.35 * (rawTarget.z - p.z) );

      const ax = clamp(kp.x * ex + kd.x * (0.5 * refVel.x - vf.x) + ki.x * intPos.x - distComp.x, -4.2, 4.2);
      const az = clamp(kp.z * ez + kd.z * (0.5 * refVel.z - vf.z) + ki.z * intPos.z - distComp.z, -4.2, 4.2);
      let ay = clamp(kp.y * ey + kd.y * (0.5 * refVel.y - vf.y) + ki.y * intPos.y - distComp.y, -4.5, 5.5);

      if (targetIndex === 3 && phase === 'descend' && p.y <= 0.088 && Math.hypot(obs.pad.centre.x - p.x, obs.pad.centre.z - p.z) < 0.13) {
        ay = Math.min(ay, -2.5);
      }

      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const maxTilt = (targetIndex === 3 && phase === 'descend' && p.y < 0.16) ? 0.16 : 0.48;
      const totalAy = Math.max(2.0, g + ay);
      const pitch = clamp(Math.atan2(cy * ax - sy * az, totalAy), -maxTilt, maxTilt);
      const roll = clamp(Math.atan2(-(sy * ax + cy * az), totalAy), -maxTilt, maxTilt);

      const thrust = clamp(
        (nominalMass * (g + ay)) / (maxTotalThrust * Math.max(0.65, Math.cos(att.roll) * Math.cos(att.pitch))),
        0,
        1
      );

      const bodyX = Math.sin(att.pitch) * Math.cos(att.roll), bodyZ = -Math.sin(att.roll);
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
      const dirZ = -sy * bodyX + cy * bodyZ;
      const estForceMag = thrust * maxTotalThrust;
      prevCmdAcc = {
        x: (estForceMag * dirX) / nominalMass,
        y: (estForceMag * dirY) / nominalMass - g,
        z: (estForceMag * dirZ) / nominalMass,
      };

      // 7. Yaw + integral
      intYaw = clamp(intYaw + att.yaw * dt, -0.5, 0.5);
      const yawRate = clamp(-2.5 * att.yaw - 1.2 * intYaw - 0.15 * obs.rates.yaw, -2, 2);

      return { thrust, roll, pitch, yawRate };
    },
  };
}

