import { evalSeed } from "/workspace/fast_eval.mjs";
import makeController from "/workspace/controller.js";

let pass = 0, N = 2000;
const reasons = {};
const failedSeeds = [];
let totalTime = 0, maxTime = 0;
for (let s = 1; s <= N; s++) {
  const r = evalSeed(makeController, s);
  if (r.success) {
    pass++;
    totalTime += r.simulatedSeconds;
    if (r.simulatedSeconds > maxTime) maxTime = r.simulatedSeconds;
  } else {
    reasons[r.reason] = (reasons[r.reason] || 0) + 1;
    failedSeeds.push(`${s}(${r.reason},g${r.gatesPassed},t=${r.simulatedSeconds},err=${r.landingError})`);
  }
}
